using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class EvalTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        var chatConfig = DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(context.TestRunResultsDirectory!, "eval-reports"),
            chatClientFactory: _ => CreateChatClient(),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ]);

        s_reportingConfiguration = chatConfig;
    }

    [TestMethod]
    public async Task Chat_Response_MeetsQualityThresholds()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_Response_MeetsQualityThresholds));

        IChatClient chatClient = scenario.ChatClient!;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var evalResult = await scenario.EvaluateAsync(messages, response);

        foreach (var metric in evalResult)
        {
            Assert.IsFalse(
                metric.Value.Rating == EvaluationRating.Unacceptable,
                $"Metric '{metric.Key}' was rated unacceptable. Reason: {metric.Value.Reason}");
        }
    }

    [TestMethod]
    public async Task Chat_Response_IsRelevantToPrompt()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_Response_IsRelevantToPrompt));

        IChatClient chatClient = scenario.ChatClient!;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that answers questions concisely."),
            new(ChatRole.User, "Explain what .NET Aspire is in one sentence.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var evalResult = await scenario.EvaluateAsync(messages, response);

        foreach (var metric in evalResult)
        {
            Assert.IsFalse(
                metric.Value.Rating == EvaluationRating.Unacceptable,
                $"Metric '{metric.Key}' was rated unacceptable. Reason: {metric.Value.Reason}");
        }
    }

    private static IChatClient CreateChatClient()
    {
        // Uses the Azure OpenAI endpoint configured via environment variables:
        // AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_API_KEY (or DefaultAzureCredential)
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("AZURE_OPENAI_ENDPOINT environment variable is required.");

        var apiKey = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
            ?? throw new InvalidOperationException("AZURE_OPENAI_API_KEY environment variable is required.");

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(apiKey))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();
    }
}

